create or replace view LDL_DATA_PRODUCTION.META.V_DV_SUCESSOR_STORES_GF(
	INIT_STORE_NR,
	INIT_STORE_SID,
	NEXT_STORE_NR,
	NEXT_STORE_SID,
	NEXT_STORE_SID_CREATED_TMSP,
	FAILED,
	TOTAL
) COMMENT='Sucessor Stores SID current and next with date of changes. Full history\nInput datasets\netl_process.t_tcache_lisy_cds_account_snap\nmeta.t_party_key'
 as with recur as ( SELECT repl.accountid ,repl.igl_number ,pred.accountid as prev_account_id ,pred.igl_number as prev_igl_number ,pred.igl_neodate as prev_open_dt ,pred.igl_closingdate as prev_close_dt ,1 as level FROM etl_process.t_tcache_lisy_cds_account_snap repl join etl_process.t_tcache_lisy_cds_account_snap pred on repl.accountid = pred.igl_replacementid WHERE repl.accountid in (select igl_replacementid from etl_process.t_tcache_lisy_cds_account_snap) UNION SELECT repl.accountid ,repl.igl_number ,pred.accountid as prev_account_id ,pred.igl_number as prev_igl_number ,pred.igl_neodate as prev_open_dt ,pred.igl_closingdate as prev_close_dt ,1 as level FROM etl_process.t_tcache_lisy_cds_account_snap repl join etl_process.t_tcache_lisy_cds_account_snap pred on repl.igl_substituteforid = pred.accountid WHERE repl.igl_substituteforid in (select accountid from etl_process.t_tcache_lisy_cds_account_snap) UNION ALL SELECT repl.accountid ,repl.igl_number ,pred.accountid      as prev_account_id ,pred.igl_number     as prev_igl_number ,pred.igl_neodate     as prev_open_dt ,pred.igl_closingdate as prev_close_dt ,level + 1           as level FROM recur repl join etl_process.t_tcache_lisy_cds_account_snap pred on repl.prev_account_id = pred.igl_replacementid ) , init_repl_set as ( select igl_number as descendant_igl_number ,prev_igl_number as init_igl_number ,prev_open_dt ,prev_close_dt from recur QUALIFY ROW_NUMBER() over (partition by igl_number order by level desc) = 1 and (prev_open_dt is not null or prev_close_Dt is not null) ) select substr(irs.init_igl_number, 1, 2) || '|' || to_number(substr(irs.init_igl_number, 3, length(irs.init_igl_number))) as init_store_nr , init_store_key.party_sid as init_store_sid , substr(irs.descendant_igl_number, 1, 2) || '|' || to_number(substr(irs.descendant_igl_number, 3, length(irs.descendant_igl_number))) as next_store_nr , next_store_key.party_sid as next_store_sid , next_store_key.dwh_created_tmsp as next_store_sid_created_tmsp , case when init_store_sid <> next_store_sid then 1 else 0 end as FAILED , 1 as TOTAL from init_repl_set irs inner join meta.t_party_key init_store_key on init_store_nr = init_store_key.party_nat_key_nr and init_store_key.party_key_type_cd = 'STORE' inner join meta.t_party_key next_store_key on next_store_nr = next_store_key.party_nat_key_nr and next_store_key.party_key_type_cd = 'STORE';